 A complex smart contract can be created using a blockchain platform such as Ethereum, which supports the Solidity programming language. Here's an example of a complex smart contract that includes multiple functions, events, and modifiers:

```solidity
pragma solidity ^0.8.0;

contract ComplexContract {

    struct User {
        address owner;
        uint256 balance;
    }

    User[] public users;

    event LogTransfer(address indexed from, address indexed to, uint256 amount);

    modifier onlyOwner(address _owner) {
        require(msg.sender == _owner, "Caller is not the owner.");
        _;
    }

    function addUser(address _owner) public {
        users.push(User({owner: _owner, balance: 0}));
    }

    function deposit(uint256 _amount) public {
        require(msg.sender != address(0), "Sender address is zero.");
        require(users[msg.sender].balance < 1e18, "Balance is already maxed out.");

        users[msg.sender].balance += _amount;
        emit LogTransfer(address(0), msg.sender, _amount);
    }

    function withdraw(uint256 _amount) public onlyOwner(msg.sender) {
        require(users[msg.sender].balance >= _amount, "Insufficient balance.");

        users[msg.sender].balance -= _amount;
        emit LogTransfer(msg.sender, address(0), _amount);
    }
}
```

This smart contract allows users to create an account, deposit and withdraw Ether, and logs all transactions. The `onlyOwner` modifier ensures that only the owner of an account can withdraw funds. The `LogTransfer` event logs the sender, recipient, and amount of each transaction. The contract uses the `require` statement to ensure that certain conditions are met before executing a function. The `balance` variable is stored as a `uint256` to allow for large amounts of Ether to be deposited and withdrawn.

