    public static Map<String, Integer> countColors(List<Car> cars) {
        return cars.stream()
                .collect(Collectors.groupingBy(Car::getColor, Collectors.counting()))
                .entries()
                .stream()
                .max(Map.Entry.comparingByValue())
                .orElse(null);
    }
}
```

